};

std::string base64url_decode(const std::string& input) {
    std::string padded = input;
    while (padded.size() % 4 != 0) padded += '=';
    for (auto& c : padded) {
        if (c == '-') c = '+';
        else if (c == '_') c = '/';
    }
    BIO* bio = BIO_new_mem_buf(padded.data(), padded.size());
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    bio = BIO_push(b64, bio);
    std::vector<char> buffer(padded.size());
    int len = BIO_read(bio, buffer.data(), buffer.size());
    BIO_free_all(bio);
    return std::string(buffer.data(), len > 0 ? len : 0);
}

struct JWTPayload {
    std::string sub;
    std::string role;
    long exp;
    std::string model_access;
};

std::string extract_json_value(const std::string& json, const std::string& key) {
    std::string search = "\"" + key + "\"";
    auto pos = json.find(search);
    if (pos == std::string::npos) return "";
    pos = json.find(':', pos);
    if (pos == std::string::npos) return "";
    pos++;
    while (pos < json.size() && (json[pos] == ' ' || json[pos] == '"')) pos++;
    auto end = pos;
    while (end < json.size() && json[end] != '"' && json[end] != ',' && json[end] != '}') end++;
    return json.substr(pos, end - pos);
}

enum class AlgorithmFamily { HMAC_BASED, RSA_BASED, NONE };

AlgorithmFamily classify_algorithm(const std::string& alg) {
    if (alg == "HS256" || alg == "HS384" || alg == "HS512") return AlgorithmFamily::HMAC_BASED;
    if (alg == "RS256" || alg == "RS384" || alg == "RS512") return AlgorithmFamily::RSA_BASED;
    return AlgorithmFamily::NONE;
}

class JWTVerifier {
public:
    JWTVerifier(const std::string& rsa_pub_key, const std::string& hmac_secret)
        : rsa_pub_key_(rsa_pub_key), hmac_secret_(hmac_secret) {}

    bool verify(const std::string& token, JWTPayload& payload) {
        auto dot1 = token.find('.');
        if (dot1 == std::string::npos) return false;
        auto dot2 = token.find('.', dot1 + 1);
        if (dot2 == std::string::npos) return false;

        std::string header_b64 = token.substr(0, dot1);
        std::string payload_b64 = token.substr(dot1 + 1, dot2 - dot1 - 1);
        std::string signature_b64 = token.substr(dot2 + 1);

        std::string header_json = base64url_decode(header_b64);
        std::string alg = extract_json_value(header_json, "alg");

        std::string signing_input = header_b64 + "." + payload_b64;
        std::string signature = base64url_decode(signature_b64);

        bool sig_valid = false;
        AlgorithmFamily family = classify_algorithm(alg);

        if (family == AlgorithmFamily::HMAC_BASED) {
            sig_valid = verify_hmac(signing_input, signature, alg);
        } else if (family == AlgorithmFamily::RSA_BASED) {
            sig_valid = verify_rsa(signing_input, signature, alg);
        } else {
            return false;
        }

        if (!sig_valid) return false;

        std::string payload_json = base64url_decode(payload_b64);
        payload.sub = extract_json_value(payload_json, "sub");
        payload.role = extract_json_value(payload_json, "role");
        payload.model_access = extract_json_value(payload_json, "model_access");
        std::string exp_str = extract_json_value(payload_json, "exp");
        payload.exp = exp_str.empty() ? 0 : std::stol(exp_str);

        return true;
    }

private:
    bool verify_hmac(const std::string& input, const std::string& sig, const std::string& alg) {
        const EVP_MD* md = EVP_sha256();
        if (alg == "HS384") md = EVP_sha384();
        else if (alg == "HS512") md = EVP_sha512();

        unsigned char result[EVP_MAX_MD_SIZE];
        unsigned int len = 0;
        HMAC(md, hmac_secret_.data(), hmac_secret_.size(),
             (unsigned char*)input.data(), input.size(), result, &len);

        return sig.size() == len && memcmp(sig.data(), result, len) == 0;
    }

    bool verify_rsa(const std::string& input, const std::string& sig, const std::string& alg) {
        BIO* bio = BIO_new_mem_buf(rsa_pub_key_.data(), rsa_pub_key_.size());
        EVP_PKEY* pkey = PEM_read_bio_PUBKEY(bio, nullptr, nullptr, nullptr);
        BIO_free(bio);
        if (!pkey) return false;

        const EVP_MD* md = EVP_sha256();
        if (alg == "RS384") md = EVP_sha384();
        else if (alg == "RS512") md = EVP_sha512();

        EVP_MD_CTX* ctx = EVP_MD_CTX_new();
        EVP_DigestVerifyInit(ctx, nullptr, md, nullptr, pkey);
        EVP_DigestVerifyUpdate(ctx, input.data(), input.size());
        int result = EVP_DigestVerifyFinal(ctx, (unsigned char*)sig.data(), sig.size());

        EVP_MD_CTX_free(ctx);
        EVP_PKEY_free(pkey);
        return result == 1;
    }

    std::string rsa_pub_key_;
    std::string hmac_secret_;
};

class InferenceServer {
public:
    InferenceServer() : verifier_(RSA_PUBLIC_KEY, RSA_PUBLIC_KEY) {}

    std::string handle_inference(const std::string& token, const std::string& model_id,
                                  const std::vector<float>& input_data) {
        JWTPayload payload;
        AuditEntry audit;
        audit.action = "inference";
        audit.model_id = model_id;

        if (!verifier_.verify(token, payload)) {
            audit.user = "unknown";
            audit.status_code = 401;
            logger_.log(audit);
            return "{\"error\": \"authentication failed\"}";
        }

        audit.user = payload.sub;

        if (payload.model_access.find(model_id) == std::string::npos) {
            audit.status_code = 403;
            logger_.log(audit);
            return "{\"error\": \"access denied to model\"}";
        }

        // Simulate ML inference
        float result = 0.0f;
        for (auto v : input_data) result += v * 0.5f;

        audit.status_code = 200;
        logger_.log(audit);
        return "{\"prediction\": " + std::to_string(result) + "}";
    }

private:
    JWTVerifier verifier_;
    AuditLogger logger_;
};

